// The comparative bank generator's pure half (spec 009 FR-028 to FR-031, research R12, task T055): deterministic output, the
// unit's questions with their texts, choice and concept ids, the key (with its pairing) kept out of the public file, texts
// that are new to the store joining it (and only through 008's generator), pending questions kept out, and every problem
// listed at once. With no comparative bank at all the generated files are exactly the committed empty ones, so spec 008's
// output cannot change.

import fs from "node:fs";
import path from "node:path";

import { describe, expect, it } from "vitest";

import { buildComparativeFiles, newStoreTexts, withoutPendingComparative, type ComparativeBankFile } from "../../scripts/comparative-build-bank-lib";
import { buildFiles, type BankFile } from "../../scripts/unseen-build-bank-lib";

const CMP = "y12-english-advanced-comparative-texts";
const KNOWN = new Set(["old-t1", "old-t2", "old-t3"]);

const newText = (id: string, visual = false): ComparativeBankFile["texts"][number] => ({
  id, form: visual ? "visual" : "prose-fiction", heading: `Text 5 – ${visual ? "Image" : "Prose"}`, title: "T", author: "A", sourceLine: "As printed.",
  body: visual ? { kind: "image", image: id, alt: "A picture" } : { kind: "prose", paragraphs: ["Words."] }, hscChecked: "2026-11-19",
  ...(visual ? { description: "A grey photograph of an empty chair." } : {}),
});
const key = (over = {}) => ({
  criteria: "6 – Skilful\n5 – Effective\n4 – Sound\n3 – Some\n2 – Limited\n1 – Little", notes: "None provided by the school.", model: "A model answer.",
  modelOrigin: "school" as const, criteriaOrigin: "school" as const, pairing: ["old-t1", "new-t5"], ...over,
});
const bank = (): ComparativeBankFile => ({
  paper: { school: "Invented School", short: "Invented", year: 2026, exam: "Trial" },
  texts: [newText("new-t5", true)],
  questions: [
    { slug: "inv26-q5", qNo: 5, maxMarks: 6, verb: "compare", prompt: "Compare how Text 1 and Text 5 explore loss.", answerLines: 18, skills: ["compares-texts", "answers-question"],
      outcome: "EAV-12-01", textIds: ["old-t1", "new-t5"], choice: null, key: key() },
    { slug: "inv26-q6", qNo: 5, maxMarks: 8, verb: "compare", prompt: "Compare Text 5 and ONE other text.", answerLines: null, skills: ["treats-both-in-depth"],
      outcome: "EAV-12-02", textIds: ["new-t5", "old-t2", "old-t3"], choice: { fixed: ["new-t5"], from: ["old-t2", "old-t3"], pick: 1 }, key: key({ pairing: ["new-t5", "old-t2"] }) },
  ],
});

describe("buildComparativeFiles", () => {
  it("writes questions.ts and keys.ts with a generated header, deterministically", () => {
    const a = buildComparativeFiles([bank()], KNOWN);
    expect(Object.keys(a)).toEqual(["questions.ts", "keys.ts"]);
    for (const f of Object.values(a)) expect(f).toContain("GENERATED by scripts/unseen-build-bank.ts");
    expect(buildComparativeFiles([bank()], KNOWN)).toEqual(a);
  });

  it("builds the public question with its texts, choice, source, skill concept ids and lines × 12 words", () => {
    const { "questions.ts": q } = buildComparativeFiles([bank()], KNOWN);
    expect(q).toContain(`"id": "${CMP}.inv26-q5"`);
    expect(q).toContain('"type": "comparative"');
    expect(q).toContain('"source": "Invented 2026 Trial, Q5"');
    expect(q).toContain('"suggestedWords": 216');
    expect(q).toContain('"suggestedFrom": "lines"');
    expect(q).toContain(`"${CMP}.c-compares-texts"`);
    expect(q).toContain('"y12-english-advanced-unseen-texts.c-answers-question"'); // the shared seven keep spec 008's concept ids
    expect(q).toContain('"choice": null');
    expect(q).toMatch(/"fixed": \[\s*"new-t5"\s*\]/);
  });

  it("uses the median for a mark value whose lines cannot be counted, and 0 (which validation refuses) where none is counted", () => {
    const { "questions.ts": q } = buildComparativeFiles([bank()], KNOWN);
    expect(q).toContain('"suggestedFrom": "median"');
    expect(q).toContain('"suggestedWords": 0'); // 8 marks: no median counted yet, so nothing ships on a guess
  });

  it("keeps the key, with its pairing, out of the public file", () => {
    const files = buildComparativeFiles([bank()], KNOWN);
    expect(files["questions.ts"]).not.toContain("A model answer.");
    expect(files["questions.ts"]).not.toContain("Skilful");
    expect(files["questions.ts"]).not.toContain('"pairing"');
    expect(files["keys.ts"]).toContain("A model answer.");
    expect(files["keys.ts"]).toContain('"pairing"');
    expect(files["keys.ts"]).toContain("SERVER ONLY: never import");
    expect(files["questions.ts"]).not.toContain("SERVER ONLY: never import");
  });

  it("lists every problem at once: a text already in the store, a missing text, an unknown skill, bad marks, a broken choice or pairing, duplicates", () => {
    const b = bank();
    b.texts.push(newText("old-t1"));
    b.questions[0].textIds = ["old-t1", "nowhere"];
    (b.questions[0].skills as string[]).push("vibes");
    b.questions[1].maxMarks = 9;
    b.questions[1].choice = { fixed: ["old-t2"], from: ["old-t3"], pick: 2 };
    b.questions[1].key.pairing = ["not-shown"];
    b.questions.push({ ...b.questions[0], slug: "inv26-q5" });
    expect(() => buildComparativeFiles([b], KNOWN)).toThrowError(/already in the shared store[\s\S]*not found[\s\S]*unknown skill vibes[\s\S]*marks must be 3 to 8[\s\S]*textIds must be[\s\S]*pairing names[\s\S]*duplicate question slug/);
  });

  it("with the real comparative bank, produces exactly the committed files (so the committed output is reproducible)", () => {
    const bankDir = path.resolve(__dirname, "../../resources/english-unseen/bank");
    const cmpDir = path.join(bankDir, "comparative");
    const known = new Set<string>();
    for (const n of fs.readdirSync(bankDir).filter((n) => n.endsWith(".json"))) {
      const b = JSON.parse(fs.readFileSync(path.join(bankDir, n), "utf8")) as BankFile;
      for (const t of b.texts) known.add(t.id);
    }
    const all: ComparativeBankFile[] = fs.existsSync(cmpDir)
      ? fs.readdirSync(cmpDir).filter((n) => n.endsWith(".json")).sort().map((n) => JSON.parse(fs.readFileSync(path.join(cmpDir, n), "utf8")) as ComparativeBankFile)
      : [];
    const { banks } = withoutPendingComparative(all);
    const files = buildComparativeFiles(banks, known);
    for (const name of ["questions.ts", "keys.ts"] as const) {
      const committed = fs.readFileSync(path.resolve(__dirname, `../../content/units/${CMP}/${name}`), "utf8").replace(/\r\n/g, "\n");
      expect(files[name]).toBe(committed);
    }
  });
});

describe("the shared store", () => {
  it("a text new to the store joins it through spec 008's generator, with its description, and the unit's own texts.ts stays a filter", () => {
    const comparative = [bank()];
    const bank008: BankFile = {
      paper: { school: "Old", short: "Old", year: 2025, exam: "Trial" },
      texts: [{ id: "old-t1", form: "poem", heading: "Text 1 – Poem", title: "P", author: "A", sourceLine: "s", body: { kind: "poem", stanzas: [["Line"]] }, hscChecked: "2026-11-19" }],
      questions: [{ slug: "old25-q1", qNo: 1, maxMarks: 3, verb: "analyse", prompt: "Analyse.", answerLines: 12, skills: ["answers-question"], outcome: "EAV-12-01", textId: "old-t1",
        key: { criteria: "3 – a\n2 – b\n1 – c", notes: "n", model: "m", modelOrigin: "school", criteriaOrigin: "school" } }],
    };
    const files = buildFiles([bank008], newStoreTexts(comparative));
    expect(files["store-texts.ts"]).toContain('"id": "old-t1"');
    expect(files["store-texts.ts"]).toContain('"id": "new-t5"');
    expect(files["descriptions.ts"]).toContain("A grey photograph of an empty chair.");
    expect(files["store-texts.ts"]).not.toContain("A grey photograph");
    // spec 008's own texts.ts lists only the texts its questions use
    expect(files["texts.ts"]).toContain("storeTexts.filter");
    expect(files["texts.ts"]).not.toContain("new-t5");
  });

  it("a new visual with no description, or with no hscChecked date, is refused", () => {
    const b = bank();
    b.texts[0].description = " ";
    expect(() => buildFiles([], newStoreTexts([b]))).toThrow(/no description for the marker/);
    const c = bank();
    c.texts[0].hscChecked = "";
    expect(() => buildFiles([], newStoreTexts([c]))).toThrow(/no hscChecked/);
  });

  it("a new text that duplicates a text of spec 008's banks is refused by the store build", () => {
    const b = bank();
    b.texts = [newText("old-t1")];
    const bank008: BankFile = { paper: { school: "Old", short: "Old", year: 2025, exam: "Trial" }, texts: [newText("old-t1")] as never, questions: [] };
    expect(() => buildFiles([bank008], newStoreTexts([b]))).toThrow(/duplicate text id old-t1/);
  });
});

describe("pending review", () => {
  it("keeps drafted material with no reviewedOn out of the unit, and a new text only a pending question shows", () => {
    const b = bank();
    b.questions[1].key.modelOrigin = "drafted"; // pending: no reviewedOn
    const out = withoutPendingComparative([b]);
    expect(out.pending).toEqual(["inv26-q6"]);
    expect(out.banks[0].questions.map((q) => q.slug)).toEqual(["inv26-q5"]);
    expect(out.banks[0].texts.map((t) => t.id)).toEqual(["new-t5"]); // still shown by the kept question
    const only = bank();
    only.questions = [only.questions[1]];
    only.questions[0].key.criteriaOrigin = "drafted";
    expect(withoutPendingComparative([only]).banks).toEqual([]);
  });

  it("keeps a drafted question once it has a reviewedOn date", () => {
    const b = bank();
    b.questions[1].key.modelOrigin = "drafted";
    b.questions[1].key.reviewedOn = "2026-11-19";
    expect(withoutPendingComparative([b]).pending).toEqual([]);
  });
});
